    # Count routes to ledge n using hops of 1 or 2.
    pass

solution.code:
def count_routes(n):
    if n <= 1:
        return 1
    return count_routes(n - 1) + count_routes(n - 2)

quests.starterCode:
def fill_scroll(n):
    # Return [ways to ledge 0, ways to ledge 1, ..., ways to ledge n].
    pass

solution.code:
def fill_scroll(n):
    ways = [1] * (n + 1)
    for i in range(2, n + 1):
        ways[i] = ways[i - 1] + ways[i - 2]
    return ways

